tasks.check:
set -o pipefail; cd "$PWD"; export PYTHONPATH=$PWD TMPDIR=/tmp; PY=/home/bcorfman/dev/freytag-forge/.venv/bin/python
test -s notes.md && cp notes.md /home/bcorfman/dev/ringer-work/adopt-families-cue-notes.md || { echo "FAIL: notes.md missing"; exit 1; }
$PY -c "import storygame,sys; sys.exit(0 if storygame.__file__.startswith('$PWD') else 1)" || { echo "FAIL: not worktree"; exit 1; }
git diff --quiet -- storygame tests/fixtures/continuity_initiative_pre_3c_adoption || { echo "FAIL: storygame or frozen fixture edited"; exit 1; }
grep -q 'Kristin can answer the families with news of the captives.' data/stories/continuity-initiative/handoffs.yaml || { echo "FAIL: cue not adopted"; exit 1; }
test "$(git diff -U0 -- data/stories/continuity-initiative/handoffs.yaml | grep -c '^[-+][^-+]')" = 2 || { echo "FAIL: handoffs.yaml changed by more than the one cue line"; git diff -- data/stories/continuity-initiative/handoffs.yaml | head -30; exit 1; }
$PY -m pytest -q --no-cov -p no:cacheprovider -n 4 tests > pytest.out 2>&1; rc=$?; tail -15 pytest.out; test $rc -eq 0 || exit 1
changed=$(git status --porcelain | awk '{print $2}' | grep '\.py$')
test -z "$changed" || { $PY -m ruff check $changed && $PY -m ruff format --check $changed || exit 1; }
git add -A -- data tests bench scripts; git diff --cached -- data tests bench scripts > /home/bcorfman/dev/ringer-work/adopt-families-cue.patch; test -s /home/bcorfman/dev/ringer-work/adopt-families-cue.patch && echo patch-exported
